-- Shared hotel media and grounded place catalogue for Myra. Apply after 202610070001_london_catalogue.sql.
alter table public.trip_requests add column if not exists travellers_count integer check (travellers_count is null or (travellers_count between 1 and 30));
alter table public.catalogue_hotels add column if not exists lat double precision;
alter table public.catalogue_hotels add column if not exists lng double precision;
alter table public.catalogue_hotels add column if not exists address text;
alter table public.catalogue_hotels add column if not exists photos text[] not null default '{}';
on conflict(city,name) do update set id=excluded.id,price_per_night_inr=excluded.price_per_night_inr,area=excluded.area,tags=excluded.tags,lat=excluded.lat,lng=excluded.lng,address=excluded.address,photos=excluded.photos;
create index if not exists catalogue_hotels_city_name on public.catalogue_hotels(lower(city),name);
create table if not exists public.catalogue_places (
 id uuid primary key default gen_random_uuid(),
 city text not null,
 name text not null,
 kind text not null check(kind in ('sight','food')),
 area text not null,
 lat double precision not null,
 lng double precision not null,
 offbeat boolean not null default false,
 interests text[] not null default '{}',
 wiki_title text not null,
 typical_cost_inr integer not null default 0 check(typical_cost_inr >= 0),
 unique(city,name,kind)
);
create index if not exists catalogue_places_city_kind on public.catalogue_places(lower(city),kind);
alter table public.catalogue_places enable row level security;
drop policy if exists "catalogue places visible" on public.catalogue_places;
create policy "catalogue places visible" on public.catalogue_places for select to anon, authenticated using (true);
revoke all on public.catalogue_places from anon, authenticated;
grant select on public.catalogue_places to anon, authenticated;
on conflict(city,name,kind) do update set area=excluded.area,lat=excluded.lat,lng=excluded.lng,offbeat=excluded.offbeat,interests=excluded.interests,wiki_title=excluded.wiki_title,typical_cost_inr=excluded.typical_cost_inr;
